**Step 2.2: Extract GUID Collision Resolver**

csharp
// MrWhoOidc.Auth/Services/GuidCollisionResolver.cs
public interface IGuidCollisionResolver
{
    Task EnsureUniqueIdsAsync(IEnumerable<User> users, CancellationToken cancellationToken);
}

public class GuidCollisionResolver : IGuidCollisionResolver
{
    private readonly AuthDbContext _context;
    private readonly ILogger<GuidCollisionResolver> _logger;

    public GuidCollisionResolver(AuthDbContext context, ILogger<GuidCollisionResolver> logger)
    {
        _context = context;
        _logger = logger;
    }

    public async Task EnsureUniqueIdsAsync(IEnumerable<User> users, CancellationToken cancellationToken)
    {
        var pendingUsers = users.Where(u => u.Id == Guid.Empty).ToList();
        if (pendingUsers.Count == 0) return;

        var desiredIds = pendingUsers.Select(u => u.Id == Guid.Empty ? GuidHelper.NewId() : u.Id).ToList();

        for (var i = 0; i < pendingUsers.Count; i++)
        {
            if (pendingUsers[i].Id == Guid.Empty)
            {
                pendingUsers[i].Id = desiredIds[i];
            }
        }

        var existingIds = await _context.Users.AsNoTracking()
            .Where(u => desiredIds.Contains(u.Id))
            .Select(u => u.Id)
            .ToListAsync(cancellationToken)
            .ConfigureAwait(false);

        if (existingIds.Count == 0) return;

        foreach (var entry in pendingUsers)
        {
            if (!existingIds.Contains(entry.Id)) continue;

            Guid newId;
            do
            {
                newId = GuidHelper.NewId();
            } while (desiredIds.Contains(newId));

            while (await _context.Users.AsNoTracking().AnyAsync(u => u.Id == newId, cancellationToken).ConfigureAwait(false))
            {
                newId = GuidHelper.NewId();
            }

            _logger.LogWarning("Detected duplicate User.Id {UserId} while saving; reassigned to {NewUserId}", entry.Id, newId);
            entry.Id = newId;
            desiredIds.Add(newId);
        }
    }
}


**Step 2.3: Extract Email Normalization Service**

csharp
// MrWhoOidc.Auth/Services/EmailNormalizationService.cs
public interface IEmailNormalizationService
{
    void NormalizeEmailFields(ChangeTracker changeTracker);
}

public class EmailNormalizationService : IEmailNormalizationService
{
    public void NormalizeEmailFields(ChangeTracker changeTracker)
    {
        NormalizeUserAccountEmails(changeTracker);
        NormalizeUserEmails(changeTracker);
        NormalizeAlternativeEmails(changeTracker);
        NormalizeRegistrationEmails(changeTracker);
    }

    private void NormalizeUserAccountEmails(ChangeTracker changeTracker)
    {
        foreach (var entry in changeTracker.Entries<UserAccount>())
        {
            if (entry.State == EntityState.Added || entry.State == EntityState.Modified)
            {
                if (entry.State == EntityState.Added || entry.Property(nameof(UserAccount.Email)).IsModified)
                {
                    entry.Entity.Email = EmailNormalizer.FormatForStorage(entry.Entity.Email, required: false, out var normalized);
                    entry.Entity.NormalizedEmail = normalized;
                }
            }
        }
    }

    private void NormalizeUserEmails(ChangeTracker changeTracker)
    {
        foreach (var entry in changeTracker.Entries<User>())
        {
            if (entry.State == EntityState.Added || entry.State == EntityState.Modified)
            {
                if (entry.State == EntityState.Added || entry.Property(nameof(User.Email)).IsModified)
                {
                    entry.Entity.Email = EmailNormalizer.FormatForStorage(entry.Entity.Email, required: false, out var normalized);
                    entry.Entity.NormalizedEmail = normalized;
                }
            }
        }
    }

    private void NormalizeAlternativeEmails(ChangeTracker changeTracker)
    {
        foreach (var entry in changeTracker.Entries<UserAlternativeEmail>())
        {
            if (entry.State == EntityState.Added || entry.State == EntityState.Modified)
            {
                if (entry.State == EntityState.Added || entry.Property(nameof(UserAlternativeEmail.Email)).IsModified)
                {
                    var formatted = EmailNormalizer.FormatForStorage(entry.Entity.Email, required: true, out var normalized)
                        ?? throw new ValidationException("Alternative email normalization returned null.");
                    entry.Entity.Email = formatted;
                    entry.Entity.NormalizedEmail = normalized ?? string.Empty;
                }
            }
        }
    }

    private void NormalizeRegistrationEmails(ChangeTracker changeTracker)
    {
        foreach (var entry in changeTracker.Entries<Registration>())
        {
            if (entry.State == EntityState.Added || entry.State == EntityState.Modified)
            {
                if (entry.State == EntityState.Added || entry.Property(nameof(Registration.Email)).IsModified)
                {
                    var formatted = EmailNormalizer.FormatForStorage(entry.Entity.Email, required: true, out var normalized)
                        ?? throw new ValidationException("Registration email normalization returned null.");
                    entry.Entity.Email = formatted;
                    entry.Entity.NormalizedEmail = normalized ?? string.Empty;
                }
            }
        }
    }
}


**Step 2.4: Simplified AuthDbContext**

csharp
public class AuthDbContext : DbContext, IDataProtectionKeyContext
{
    private readonly IGuidCollisionResolver _guidResolver;
    private readonly IEmailNormalizationService _emailNormalizer;
    private ILogger<AuthDbContext>? _logger;

    public AuthDbContext(
        DbContextOptions<AuthDbContext> options,
        IGuidCollisionResolver guidResolver,
        IEmailNormalizationService emailNormalizer)
        : base(options)
    {
        _guidResolver = guidResolver;
        _emailNormalizer = emailNormalizer;
