// MrWhoOidc.Auth/Services/GuidCollisionResolver.cs
public interface IGuidCollisionResolver
{
    Task EnsureUniqueIdsAsync(IEnumerable<User> users, CancellationToken cancellationToken);
}

public class GuidCollisionResolver : IGuidCollisionResolver
{
    private readonly AuthDbContext _context;
    private readonly ILogger<GuidCollisionResolver> _logger;

    public GuidCollisionResolver(AuthDbContext context, ILogger<GuidCollisionResolver> logger)
    {
        _context = context;
        _logger = logger;
    }

    public async Task EnsureUniqueIdsAsync(IEnumerable<User> users, CancellationToken cancellationToken)
    {
        var pendingUsers = users.Where(u => u.Id == Guid.Empty).ToList();
        if (pendingUsers.Count == 0) return;

        var desiredIds = pendingUsers.Select(u => u.Id == Guid.Empty ? GuidHelper.NewId() : u.Id).ToList();

        for (var i = 0; i < pendingUsers.Count; i++)
        {
            if (pendingUsers[i].Id == Guid.Empty)
            {
                pendingUsers[i].Id = desiredIds[i];
            }
        }

        var existingIds = await _context.Users.AsNoTracking()
            .Where(u => desiredIds.Contains(u.Id))
            .Select(u => u.Id)
            .ToListAsync(cancellationToken)
            .ConfigureAwait(false);

        if (existingIds.Count == 0) return;

        foreach (var entry in pendingUsers)
        {
            if (!existingIds.Contains(entry.Id)) continue;

            Guid newId;
            do
            {
                newId = GuidHelper.NewId();
            } while (desiredIds.Contains(newId));

            while (await _context.Users.AsNoTracking().AnyAsync(u => u.Id == newId, cancellationToken).ConfigureAwait(false))
            {
                newId = GuidHelper.NewId();
            }

            _logger.LogWarning("Detected duplicate User.Id {UserId} while saving; reassigned to {NewUserId}", entry.Id, newId);
            entry.Id = newId;
            desiredIds.Add(newId);
        }
    }
}


