public class AuthDbContext : DbContext, IDataProtectionKeyContext
{
    private readonly IGuidCollisionResolver _guidResolver;
    private readonly IEmailNormalizationService _emailNormalizer;
    private ILogger<AuthDbContext>? _logger;

    public AuthDbContext(
        DbContextOptions<AuthDbContext> options,
        IGuidCollisionResolver guidResolver,
        IEmailNormalizationService emailNormalizer)
        : base(options)
    {
        _guidResolver = guidResolver;
        _emailNormalizer = emailNormalizer;
    }

    // DbSets only - no business logic
    public DbSet<Tenant> Tenants => Set<Tenant>();
    public DbSet<UserAccount> UserAccounts => Set<UserAccount>();
    public DbSet<User> Users => Set<User>();
    public DbSet<Client> Clients => Set<Client>();
    // ... other DbSets

    public DbSet<DataProtectionKey> DataProtectionKeys { get; set; } = null!;

    public override async Task<int> SaveChangesAsync(CancellationToken cancellationToken = default)
    {
        var pendingUsers = ChangeTracker.Entries<User>()
            .Where(e => e.State == EntityState.Added)
            .Select(e => e.Entity)
            .ToList();

        await _guidResolver.EnsureUniqueIdsAsync(pendingUsers, cancellationToken);
        _emailNormalizer.NormalizeEmailFields(ChangeTracker);

        return await base.SaveChangesAsync(cancellationToken).ConfigureAwait(false);
    }

    public override async Task<int> SaveChangesAsync(bool acceptAllChangesOnSuccess, CancellationToken cancellationToken = default)
    {
        var pendingUsers = ChangeTracker.Entries<User>()
            .Where(e => e.State == EntityState.Added)
            .Select(e => e.Entity)
            .ToList();

        await _guidResolver.EnsureUniqueIdsAsync(pendingUsers, cancellationToken);
        _emailNormalizer.NormalizeEmailFields(ChangeTracker);

        return await base.SaveChangesAsync(acceptAllChangesOnSuccess, cancellationToken).ConfigureAwait(false);
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        base.OnModelCreating(modelBuilder);

        // Apply all configuration classes from this assembly
        modelBuilder.ApplyConfigurationsFromAssembly(typeof(AuthDbContext).Assembly);
        ConfigureLicenseEntities(modelBuilder);
    }

    private static void ConfigureLicenseEntities(ModelBuilder modelBuilder)
    {
        ArgumentNullException.ThrowIfNull(modelBuilder);
        modelBuilder.ApplyConfiguration(new LicenseConfiguration());
        modelBuilder.ApplyConfiguration(new LicenseHistoryEntryConfiguration());
        modelBuilder.ApplyConfiguration(new FeatureUsageMetricConfiguration());
        modelBuilder.ApplyConfiguration(new LicenseLimitConfiguration());
    }

    private ILogger<AuthDbContext>? Logger => _logger ??= this.GetService<ILogger<AuthDbContext>>();
}


